  // которое написал человек (кириллическое имя откатило бы перевод всей подписи), и нативные вопросы.
  function trNow(s){ return LANG==='en' ? i18nStr(s) : s; }
  function askConfirm(msg){ return window.confirm(LANG==='en' ? i18nStr(msg) : msg); }
  // То же и для ЗАПРОСА ВВОДА: `window.prompt` — такой же нативный попап мимо DOM. Без обёртки
  // англоязычный получал переведённые подтверждения и русские вопросы «Новое имя подписки:» —
  // половина диалогов на одном языке, половина на другом.
  function askPrompt(msg, def){ return window.prompt(LANG==='en' ? i18nStr(msg) : msg, def); }
  function getToken(){
    if(TOKEN) return Promise.resolve(TOKEN);
    return fetch('/cgi-bin/token',{cache:'no-store'})
      .then(function(r){ return r.json(); })
      .then(function(d){ TOKEN=d.token; return TOKEN; });
  }
  // Единый POST с CSRF-токеном + АВТО-РЕТРАЙ при протухшем токене. Токен кэшируется
  // (getToken), но после ребута роутера /tmp/enodia-panel-token регенерится → кэш протухал и
  // КАЖДЫЙ POST падал «неверный токен» до ручного F5. Тут: если сервер отверг токен —
  // сбрасываем кэш, добираем свежий и повторяем РОВНО раз (токен-чек в cgi идёт ДО любого
