    // Число ВКЛЮЧЁННЫХ выходов нужно ленте технического состояния — она рисуется по тому же
    // опросу, а не своим запросом: второй источник одного числа разошёлся бы с первым.
    cur.exitsOn=(d.exits_on|0);
    // Сколько выходов не везёт — тоже факт статуса: экран устройства по нему перерисовывает путь выхода (ревью шага 4b, круг 3).
    cur.exitsBad=(d.exits_bad|0);
    var exInd=document.getElementById('exit-ind');
    if(exInd){
      var exBad=cur.exitsBad;
      exInd.style.display = exBad>0 ? 'inline-flex' : 'none';
      if(exBad>0) exInd.querySelector('span').textContent = exBad>1 ? (exBad+' '+plu(exBad,['выход','выхода','выходов'])+' не работают') : 'выход не работает';   // up to 6 exits since 05.10: «5 выходов»
    }
    // РЯД индикаторов гасим ВМЕСТЕ с ними. Пустой ряд не «ничего»: он лежит в колонке с
    // зазором 14 px, и при обоих скрытых индикаторах над шапкой оставалась дырка ровно в этот
    // зазор. `:empty` тут бессилен — дети есть, они просто display:none (замер 10.09.2026).
    var hinds=document.querySelector('.hinds');
    if(hinds){
      var anyInd=(supInd && supInd.style.display!=='none') || (exInd && exInd.style.display!=='none');
      hinds.style.display = anyInd ? '' : 'none';
    }
    // Непрочитанные события едут в общем статусе — колокольчик обновляется на том же
    // поллинге, отдельный запрос на каждый тик не нужен.
    paintBell(d.events_unread, _stAskedAt);
    // ЛЕНТА ЖИВЁТ СВОИМ ТАЙМЕРОМ (60 с), НО ОБЕСЦЕНИВАЮТ ЕЁ СОБЫТИЯ, КОТОРЫЕ ПРИХОДЯТ СЮДА:
    // сменился транспорт, поднялся или погас туннель, выключили VPN. У несущей при этом
    // ИСЧЕЗАЕТ MTU, а у DNS меняется путь — ждать до минуты значило бы показывать MTU туннеля,
    // которого уже нет. Первый кадр ключ только ЗАПОМИНАЕТ: начальную загрузку делает старт.
    var tkey=cur.transport+'|'+(cur.live?1:0)+'|'+(cur.vpnOff?1:0)+'|'+(cur.dead?1:0);
    if(_techKey!==null && tkey!==_techKey) loadTech(true);
    _techKey=tkey;
    // ВЕРДИКТ СТОРОЖА ДЛЯ ЧИПА ЛЕНТЫ — из этого же ответа, как число выходов: второй запрос ради чипа
    // дал бы ленте свою правду рядом с экраном «Режим и failover». Поля — белым списком cgi-bin/status.
    cur.fo={standing:d.standing||'', back:d.back||'', back_to:d.back_to||'', back_why:d.back_why||'', home_why:d.home_why||''};
    paintTech();   // лента под шапкой: число выходов и вердикт сторожа приезжают этим же опросом
    var ico=document.getElementById('vico-i');
    if(ico) ico.className='ti ' + (ok?'ti-shield-check':'ti-shield-off');
    var ft=(d.full_tunnel===true||d.full_tunnel==='true');   // весь трафик в туннель (не сплит)
    cur.full=ft;   // «Весь остальной трафик» на странице «Маршрутизации»
    // Подпись карточки «Режим и failover» — ГОВОРИТ О СОСТОЯНИИ, а стояла в HTML статикой «весь
    // трафик в VPN · авто-резерв». Режим по умолчанию — СПЛИТ, то есть первый экран врал почти
    // каждому: внутри карточки честное «сейчас: раздельно (только заблокированное)», снаружи
    // обратное. Второй перевод («заблокированные сайты через VPS · …») лежал в словаре мёртвым
    // ключом с самой локализации — подпись задумывалась динамической, проводку потеряли.
    // Хвост подписи — ПО ВЕРДИКТУ СТОРОЖА (status: standing/fo_mode): статичное «авто-резерв» стояло и
    // при режиме «Выкл», и на резерве карточка об этом молчала. Старый сторож без верба полей не даёт —
    // тогда хвоста нет, а не выдуманный режим. Строки целиком — ключи словаря (узел один).
    var fm=d.fo_mode, fs=d.standing;
    var foTail = fs==='none' ? ' · протокол не выбран'
               : fs==='off' ? ' · VPN выключен' : fs==='direct' ? ' · прямой режим' : fs==='boot' ? ' · загружается'
               : fs==='reserve' ? ' · на резерве'
               : fm==='off' ? ' · без авто-резерва' : fm==='home' ? ' · авто-резерв с возвратом'
               : fm==='sticky' ? ' · авто-резерв' : '';
    _modeBase=(ft?'весь трафик в VPN':'заблокированные сайты через VPS');
    t('card-mode-sub', _modeBase+foTail);
    // «СЕЙЧАС» НА ОТКРЫТОМ ЭКРАНЕ — ОТ ЭТОГО ЖЕ ОПРОСА. Блок весь временнОй («не раньше чем через N
    // мин», помеха попытке), а строился РОВНО ОДИН РАЗ, при открытии экрана: оставленный открытым
    // экран показывал замороженный ответ сторожа — срок не таял, снятая помеха не исчезала (ревью
    // подшага 2, круг 14). Своего таймера и своего запроса не заводим: статус приезжает сюда раз в
    // 10 с, а перевод добавленных узлов делает глобальный наблюдатель i18n. Гард — общий
    // screenAlive: ушли на соседний экран или закрыли модалку ⇒ не рисуем.
    var fnow=document.getElementById('fo-now');
    if(fnow && screenAlive(fnow)) fnow.innerHTML=foNowHtml(d);
    // ВТОРОЙ ВРЕМЕННЫ́Й УЗЕЛ ТОГО ЖЕ ЭКРАНА: строка «Домашний сервер» показывается по АКТИВНОМУ
    // транспорту, а хвост «сторож возьмёт …» — по `back`/`back_to`. Оставшись замороженной, она
    // спорила с обновившимся «Сейчас» в том же окне (круг 19). Сторожит проводку C102.
    var fhsrv=document.getElementById('fo-hsrv');
    if(fhsrv && screenAlive(fhsrv)) fhsrv.innerHTML=foHomeSrvHtml(d);
