    var old=document.getElementById('modal-body');
    var m=document.getElementById('modal');
    if(old && old.parentNode){
      var fresh=document.createElement('div'); fresh.id='modal-body';
      // ПЕРЕРИСОВКА ТОГО ЖЕ ЭКРАНА (тот же адрес, не шаг поверх) держит высоту прежнего тела, пока не придёт ответ: иначе
      // «Загрузка…» схлопывала страницу, браузер сбрасывал прокрутку в 0, и человек, нажавший тумблер внизу длинной колоды на
      // телефоне, оказывался наверху экрана, а фокус возвращался на узел вне видимой области (ревью шага 3c-3, круг 1).
      if(m && m.classList.contains('open') && o.route && !_navTransient && navKey(o.route, o.arg)===_navKey) scrHold(fresh, old);
      old.parentNode.replaceChild(fresh, old);
    }
