  function screenAlive(node){
    return !!node && document.body.contains(node) && document.getElementById('modal').classList.contains('open');
  }
  function esc(s){ return String(s).replace(/[&<>"]/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]; }); }
  // Копировать ПЛАЙН-строку в буфер (Clipboard API + textarea-фолбэк для старых/не-HTTPS). Тост о результате.
  function copyToClip(txt, okmsg){
    txt=String(txt||''); okmsg=okmsg||'скопировано';
    function done(ok){ showToast(ok?okmsg:'не удалось скопировать', ok); }
    function fallback(){
      try{ var ta=document.createElement('textarea'); ta.value=txt; ta.style.position='fixed'; ta.style.top='-1000px'; ta.style.opacity='0';
        document.body.appendChild(ta); ta.focus(); ta.select(); var ok=document.execCommand('copy'); document.body.removeChild(ta); done(ok); }
      catch(e){ done(false); }
    }
    if(navigator.clipboard && navigator.clipboard.writeText){ navigator.clipboard.writeText(txt).then(function(){ done(true); }, fallback); }
    else { fallback(); }
  }
  // Числовое согласование (рус): plu(3521,['подсеть','подсети','подсетей'])→'подсеть', plu(1,…)→ед.
  function plu(n,a){ n=Math.abs(+n||0)%100; var d=n%10; if(n>10&&n<20)return a[2]; if(d>1&&d<5)return a[1]; if(d===1)return a[0]; return a[2]; }
  var UNIT_FORMS={'подсетей':['подсеть','подсети','подсетей'],'правил':['правило','правила','правил'],'доменов':['домен','домена','доменов'],'записей':['запись','записи','записей'],'источника/-ов':['источник','источника','источников'],'адресов':['адрес','адреса','адресов'],'событий':['событие','события','событий'],'групп':['группа','группы','групп'],'устройств':['устройство','устройства','устройств'],'строк':['строка','строки','строк'],'пакетов':['пакет','пакета','пакетов'],'серверов':['сервер','сервера','серверов'],'дней':['день','дня','дней']};
  function unitF(n,u){ var f=UNIT_FORMS[u]; return f?plu(n,f):u; }
  // base64 UTF-8-safe (для содержимого конфига при загрузке).
  function b64utf8(str){ return btoa(unescape(encodeURIComponent(str))); }
