      + lrowGo('2fa')+'<span class="dot'+TF_W[s][0]+'"></span><div class="grow"><div class="nm">'+TF_W[s][1]+'</div><div class="ds">'+tfDs(tf)+'</div></div>'+CHEV+'</div>'
