      var rest=pool.querySelectorAll('.fc,.door'), lost=[];
      for(var j=0;j<rest.length;j++){ if(!seen[rest[j].id]){ lost.push(rest[j].id||'без id'); _secBox.rr.appendChild(rest[j]); } }
