    // номер выхода 2..7).
    'cn-sub':      {back:'cn-subs', t:'Подписка', need:1, via:'openSub', arg:function(a){ return subTagOk(a); }, open:function(a){ subScrOpen(a); }},
    'cn-exits':    {back:'cn', t:'Дополнительные выходы',         open:function(){ openExits(); }},
    'cn-exit':     {back:'cn-exits', t:'Выход', need:1, via:'openExit', arg:function(a){ return bpSlotOk(a); }, open:function(a){ exitScrOpen(a); }},
    'cn-failover': {back:'cn', t:'Режим и резервирование',        open:function(){ openMode(); }},
    // Без номера — десинк основной несущей; с номером — стратегия выхода, и её родитель — экран этого выхода.
    'cn-byedpi':   {back:function(a){ return a?navKey('cn-exit', a):'cn'; }, t:'ByeDPI',
                    arg:function(a){ return a===''||bpSlotOk(a); },   open:function(a){ openByedpi(a); }},
    'cn-zapret':   {back:'cn', t:'Zapret',      open:function(){ openZapret(); }},
    'cn-home':     {back:'cn', t:'Доступ домой',                  open:function(){ openVpnSrv(); }},
    'cn-checks':   {back:'cn', t:'Проверка серверов',             open:function(){ openChecks(); }},
    'cn-peer':     {back:'cn-home', need:1, via:'openVpnSrvPeer', arg:function(a){ return /^[2-9]$/.test(a); }, open:function(a){ vsPeerOpen(a); }},
    // Экран БЕЗ АРГУМЕНТА, но и без последствий на роутере: «назад» и перезагрузка открывают пустой лист, а
