    'rt-new':      {back:'rt', t:'Новое правило',                  open:function(){ openRuleNew(); }},
    // Импорт — тоже без последствий на открытии (шаг 4d-3): закачку подписки начинает кнопка или клик в её меню, а адрес
    // лишь открывает черновик.
    'rt-import':   {back:'rt', t:'Импорт правил',                  open:function(){ openRuleImport(); }},
    'rt-dev':      {back:'rt', t:'Устройство', need:1, arg:argIp, open:function(a){ openDevice(a); }},
    'rt-groups':   {back:'rt', t:'Группы правил',                 open:function(){ openGroups(); }},
    // Группа — по номеру `gN`; имя и состав знает роутер, разрешитель сперва спрашивает его (как у выхода).
    'rt-group':    {back:'rt-groups', t:'Группа', need:1, via:'openGroup', arg:function(a){ return /^g[0-9]{1,6}$/.test(a); }, open:function(a){ grpScrOpen(a); }},
    // Хаб источников: без аргумента — туннельный список, с аргументом — своя категория (дверь пула с экрана Zapret).
