    'rt-geo':      {back:'rt', t:'Гео-списки', open:function(){ openGeo(); }},
    'nw-block':    {back:'nw', t:'Блокировка',                    open:function(){ openBlocking(); }},
    'nw-wifi':     {back:'nw', t:'Wi-Fi и подсети',               open:function(){ openWifi(); }},
    // DNS-часть и сетевые тумблеры «Настроек» — свои экраны раздела «Сеть» (шаг 5a).
    'nw-dns':      {back:'nw', t:'Шифрованный DNS',               open:function(){ openDns(); }},
    'nw-hosts':    {back:'nw', t:'Свои имена',                    open:function(){ openDnsHosts(); }},
    'nw-tune':     {back:'nw', t:'Параметры сети',                open:function(){ openNetTune(); }},
    'rr-pkg':      {back:'rr', t:'Компоненты',                    open:function(){ openPackages(); }},
    'rr-disk':     {back:'rr', t:'Место и накопитель',            open:function(){ openDisk(); }},
    'rr-ram':      {back:'rr', t:'Память и процессы',             open:function(){ openRam(); }},
    'rr-update':   {back:'rr', t:'Обновление',                    open:function(){ openUpdate(); }},
    'rr-info':     {back:'rr', t:'О роутере',                     open:function(){ openSysinfo(); }},
    'rr-support':  {back:'rr', t:'Режим поддержки',               open:function(){ openSupport(); }},
    'rr-diag':     {back:'rr', t:'Диагностика',                   open:function(){ openDiag(); }},
    'rr-console':  {back:'rr', t:'Консоль',                       open:function(){ openConsole(); }},
    'rr-tasks':    {back:'rr', t:'Задачи',                        open:function(){ openTasks(); }},
    // Задача — по номеру `tN`; имя и настройки знает роутер, разрешитель сперва спрашивает его (как у группы). Открытие
