    // или в неё ещё не вошли. Прежде вход под английским оставлял вкладке русское «Enodia — панель роутера» (ревью шага 8a).
    var bare=_panelGone ? 'Панель удалена' : _2faOpen ? 'Подтверждение входа' : _loginOpen ? 'Вход в панель' : '';
    if(bare){ document.title=(LANG==='en' ? i18nStr(bare) : bare)+' · Enodia'; return; }
    if(typeof SEC!=='object' || !SEC) return;          // язык применяют и до разметки разделов
    var mt=document.getElementById('modal-title'), b=document.body;
    var nm=screenOpen() ? ((mt||{}).textContent||'')
                        : (_curSec!=='ov' && SEC[_curSec] ? SEC[_curSec].nm : '');
    // Режим стримера: вкладку не размыть, поэтому имя из данных человека заменяем общим именем экрана из реестра.
    // Имя из данных (заголовок с `sens`) не переводим — как и в самом заголовке (scrTitle); а подменённое стримером имя из
    // реестра — наше слово и переводится (ревью ветки fix/awg-exits, круг 2: под английским вкладка оставалась «Устройство»).
    var dataNm=screenOpen() && mt && mt.classList && mt.classList.contains('sens');
