  window.addEventListener('resize', placeChrome);
  /* ВЕРСИЯ В ПОДВАЛЕ САЙДБАРА. Секция `update` локальная (читает VERSION и наличие бинарей,
     в сеть не ходит), но всё же форки — поэтому спрашиваем один раз и с задержкой, после
     первого статуса: подвал не то, ради чего стоит задерживать первый кадр. */
  setTimeout(function(){
    fetchJson('/cgi-bin/data?section=update').then(function(d){
      t('ver-num', (d && d.version) ? d.version : '—');
    }).catch(function(){ t('ver-num','—'); });   // «…» навсегда читается как «сейчас догрузится»
  }, 1800);

  // ==================== ПОРЯДОК СТАРТА (шаг 2k переноса) ====================
  // ПЕРВЫМ — СТАТУС. Первый кадр держат шапка и меры (заставка ждёт именно их), а браузер ведёт к
  // одному адресу не больше шести соединений разом: стоило карточкам колоды и трафику уйти раньше
  // (так и было — их будил `paintSec`), и статус вставал в очередь седьмым-девятым. ЗАМЕР BE7000
  // 11.09.2026: статус первым в пачке — 230–275 мс, в хвосте той же пачки — 425–450 мс, в
  // одиночку — 210–220. То есть почти вся цена — очередь браузера, а не роутер, и лечится она
  // порядком, а не придерживанием остальных запросов. За статусом — лента и строка адресов (тоже
  // первый экран), затем раскладка колоды, и только потом карточки.
  // Кости шапки и ленты держат высоту ПРОШЛОГО кадра (разбор у sklHold), мера накопителя — своё
  // место из кэша (разбор в paint). Всё это — до первого кадра: заставка уйдёт уже над готовым.
  sklHold(document.getElementById('hero'), 'hero', 0, false);
  sklHold(document.getElementById('techbar'), 'tech', 0, false);
  try{ if(localStorage.getItem('enodia_gstore')==='1'){ var _gcs=document.getElementById('gc-store'); if(_gcs) _gcs.style.display=''; } }catch(e){}
  // Мер стало четыре (из кэша) — телефонная шапка меряется заново; и ещё раз, когда доедет шрифт: слово бренда в запасном шрифте уже.
  pheadFit(true);
  try{ if(document.fonts && document.fonts.ready) document.fonts.ready.then(function(){ pheadFit(true); }); }catch(e){}
  // Обёртка, а не сама функция: аргумент `load` значит «вызов после действия» (разбор у _stGate).
  load();        _statusTimer=setInterval(function(){ load(); }, 10000);
  // Лента технического состояния — раз в минуту: DNS-путь и MTU несущей меняются событиями
  // (сторож, fail-open, смена транспорта), а не непрерывно; после действий её будит postAction.
  loadTech();    _techTimer=setInterval(function(){ loadTech(); }, 60000);
  // Обёртка, а НЕ `setInterval(loadIp, …)`: таймер в части браузеров передаёт колбэку «опоздание»
  // числом, оно попало бы в аргумент force — и каждый поллинг обходил бы кэш роутера.
  loadIp();      _ipTimer=setInterval(function(){ loadIp(); }, 60000);
  // НАСТРОЙКИ — ТОЖЕ ПЕРВЫЙ ЭКРАН: из них язык и тема (роутер — истина, кэш браузера мог отстать),
  // чип IPv6 ленты и источник живой скорости. Стояли они за колодой, и первый кадр ленты ждал бы их
  // лишнюю секунду (разбор у techSettle). Один раз при старте, кэш PREFS; как только известен
  // интервал автопроверки — фоновый автопинг, и при включённом первый обход почти сразу («зашёл в
  // панель → пинги уже свежие», не дожидаясь полного тика).
  loadPrefs().then(function(){ apStart(); if(PREFS.autoping_min>0) setTimeout(function(){ if(!document.hidden && apStale()) autoPingSweep(); }, 4000); });
  // РАСКЛАДКА — ДО ПЕРВОГО ОПРОСА КАРТОЧЕК. Раньше колоду будил `paintSec` из навигации, то есть
  // ДО `setupCards`: карточки, выключенные человеком, спрашивались на каждом старте (`mc-off`
  // ещё не стоял), и обещание экрана «Карточки главной» — «выключенная карточка — меньше работы
  // роутеру» — не выполнялось ровно на первом кадре. Здесь же встают и кости карточек.
  setupCards();
  layoutFetch();   // подтянуть раскладку с роутера (истина для мульти-девайс) поверх localStorage-кэша
  // Раздел из адреса + первый тик колоды и трафика (ovKick): спрошены будут только ВИДИМЫЕ.
  paintSec();
  getToken();
  loadPing();    _pingTimer=setInterval(function(){ loadPing(); }, 10000);   // обёртка: аргумент таймера стал бы «кликом»
  loadChecks();  // запомненные пинг/скорость серверов (.srv-checks на роутере) — для hydrateChecks
  // Вернулись на вкладку панели после отсутствия → освежить пинги, но ТОЛЬКО если кэш протух (apStale):
  // мелькание на другую вкладку и обратно не должно каждый раз перепинговывать все подписки (троттл 60с сверху).
  document.addEventListener('visibilitychange', function(){ if(!document.hidden && PREFS.autoping_min>0 && (Date.now()-apLastSweep>60000) && apStale()) autoPingSweep(); });
  // ЧИПЫ ИСТОЧНИКА ЖИВОЙ СКОРОСТИ — настоящие <button> (Enter и пробел работают сами), один
  // делегированный обработчик на группу: сами кнопки не пересоздаются, меняется только их вид.
  // Подсказки ставим ОДИН раз: перерисовка раз в пять секунд переписывала бы их, а словарь —
  // заново переводил. Источник строк — та же таблица LIVE_TIP, что у плитки экрана.
  (function(){
    var grp=document.getElementById('hlive-src'); if(!grp) return;
    Array.prototype.forEach.call(grp.querySelectorAll('[data-lsrc]'), function(b){ b.title=LIVE_TIP[b.getAttribute('data-lsrc')]||''; });
    grp.addEventListener('click', function(e){
      var n=e.target;
      while(n && n!==grp){ if(n.getAttribute && n.getAttribute('data-lsrc')){ liveSrcSet(n.getAttribute('data-lsrc'), true); return; } n=n.parentNode; }
    });
  })();
  // Первый кадр — из кэша (разбор у heroLiveShow): блок встаёт на место ДО статуса (в скелетоне
  // шапки он уже держит своё место), а рисует его первый же ответ трафика, кто бы его ни спросил —
  // `paintSec` выше или показ блока: второй упрётся в гард «один запрос в воздухе».
  try{ if(localStorage.getItem('enodia_hlive')==='1' && heroLiveShow(true)) loadTraffic(); }catch(e){}
  // Обёртка, а не сама функция: аргумент у `loadTraffic` значит «это выбор человека», и таймер
  // не должен передавать туда ничего своего. Первый опрос уже ушёл из `paintSec`.
  // `trafStuck` — повисший первый ответ не держит кости карточек трафика дольше потолка.
  _trafTimer=setInterval(function(){ loadTraffic(); liveStale(); trafStuck(); }, 5000);
  // Линию в шапке рисуем в пикселях контейнера (разбор у liveSvg), поэтому смена ширины — повод
  // перерисовать её сразу, а не ждать тика. `resize` сыплется очередями — берём последнее.
  var _hlRz=null;
  window.addEventListener('resize', function(){ if(_hlRz) clearTimeout(_hlRz); _hlRz=setTimeout(function(){ _hlRz=null; liveHeroPaint(); }, 150); });
  // КАРТОЧКИ «ОБЗОРА» — один тик на всю колоду (реестр OVC): период объявляет карточка, а тик
  // раз в 10 с лишь проверяет, кому пора и кто сейчас виден. Отдельного таймера на карточку нет
  // намеренно — см. комментарий у планировщика. Возврат на вкладку тикаем сразу: пока она была
  // в фоне, мы не спрашивали ничего, и человек увидел бы цифры той минуты, когда уходил.
  // Первый тик уже был — из `paintSec` в порядке старта.
  _ovcTimer=setInterval(ovcTick, 10000);
  document.addEventListener('visibilitychange', function(){ if(!document.hidden) ovKick(); });
  // Переключатели карточки «Трафик»: источник (VPN/напрямую/всего) и окно графика (7д/30д/год).
  // Обработчик — общий (`wireSeg`): он же чинит доступность с клавиатуры у обоих.
  // Выбор человека — `loadTraffic(true)`: гард не выбросит его, если в воздухе тик (разбор у flightGate).
  // Смена источника карточки меняет и её «сейчас» (разбор у livePaint) — перерисовываем сразу, не ждём ответа.
   // выбрал человек — авто больше не вмешивается
  // Конец старта — В САМОМ КОНЦЕ ФАЙЛА (`_bootDone`, заставка, срок скелетона): ниже ещё исполняется код
  // верхнего уровня (переменные входа и 2FA, таблицы QR; поле Галуа строит `gfInit` при первом QR), и упади он — старт был бы
  // объявлен дособранным раньше, чем дособран (независимое ревью шага 2k, круг 7).

  // ==================== ВТОРОЙ ФАКТОР ВХОДА (TOTP) =============================
  // Панель открывается наружу по WAN IP, и одного пароля там мало: HTTP-Basic браузер шлёт на
  // КАЖДЫЙ запрос и вторым фактором его не расширить (диалог рисует браузер, не мы). С 03.09.2026
  // Basic снят: первый фактор — форма входа (showLogin → cgi-bin/login, сессия уровня 1), а код
  // из приложения проверяет cgi-bin/2fa и ПОВЫШАЕТ ту же сессию до уровня 2 — его требует гейт
  // во всех остальных CGI (totp.sh). Перехват «нужен пароль/код» — в обёртке над fetch в начале
  // файла; здесь только экраны.
  function tfaPost(op, code, sid){
    return tokPost('/cgi-bin/2fa', function(tok){
      return 'op=' + encodeURIComponent(op) + '&token=' + encodeURIComponent(tok) +
             '&code=' + encodeURIComponent(code || '') +
             '&sid=' + encodeURIComponent(sid || '');
    });
  }
  // ---- УСТРОЙСТВА С ПОДТВЕРЖДЁННЫМ ВХОДОМ (список сессий 2FA) ------------------------------
  // Зачем: «Устройств: 3» не отвечает на единственный вопрос, ради которого туда смотрят, —
  // ЧТО это за третье. Реестр сессий и так лежит файлом на /data, показать и отозвать есть что.
  var tfaLanAddr='';
  // UA → человеческое имя. Разбираем ВО ФРОНТЕ: на роутере это был бы второй набор шаблонов на
  // busybox, который устареет с ближайшим браузером, а строка UA всё равно едет к нам целиком.
  // Порядок проверок = порядок вложенности подделок: Edge и Яндекс пишут в UA и «Chrome», а
  // Chrome пишет «Safari» — сначала частное, потом общее.
  function tfaUaName(ua){
    if(!ua) return 'неизвестное устройство';
    var br='', os='';
    if(/Edg/.test(ua)) br='Edge';
    else if(/YaBrowser/.test(ua)) br='Яндекс.Браузер';
    else if(/OPR|Opera/.test(ua)) br='Opera';
    else if(/Firefox/.test(ua)) br='Firefox';
    else if(/Chrome|CriOS/.test(ua)) br='Chrome';
    else if(/Safari/.test(ua)) br='Safari';
    if(/iPhone/.test(ua)) os='iPhone';
    else if(/iPad/.test(ua)) os='iPad';
    else if(/Android/.test(ua)) os='Android';
    else if(/Windows/.test(ua)) os='Windows';
    else if(/Macintosh|Mac OS/.test(ua)) os='macOS';
    else if(/Linux/.test(ua)) os='Linux';
    if(br && os) return br+' · '+os;
    return br || os || 'неизвестное устройство';
  }
  function tfaWhen(ts){
    if(!ts) return '';
    try { return new Date(ts*1000).toLocaleString(); } catch(e){ return ''; }
  }
  function tfaSessRows(list, totpOn){   // totpOn — из ТОГО ЖЕ ответа сервера (2fa sessions: поле on)
    if(!list.length) return '<div class="cline">Вошедших устройств нет.</div>';
    // Свежие сверху, текущее — первым: порядок задаём здесь, у роутера своей сортировки нет
    // (навязанный им порядок пришлось бы дублировать тут при первой же правке).
    list=list.slice().sort(function(a,b){
      if(!!a.cur!==!!b.cur) return a.cur?-1:1;
      return (b.issued||0)-(a.issued||0);
    });
    return list.map(function(s){
      // АДРЕС ЧЕСТНО: за panel-tls до CGI доезжает LAN-адрес самого роутера, отличить «зашли из
      // интернета» от «зашли из дома» панель не может в принципе — так и подписываем, а не
      // выдаём адрес роутера за адрес устройства. Настоящий адрес — под меткой стримера (`.mono`).
      var addr=!s.addr ? '<span>адрес не записан</span>'
             : (tfaLanAddr && s.addr===tfaLanAddr) ? '<span>вход по HTTPS — адрес устройства не виден</span>'
             : '<span class="mono">'+esc(s.addr)+'</span>';
      // «БЕЗ КОДА» — сессия уровня 1 при включённом 2FA: пароль принят, код второго фактора не
      // вводили, и гейт такой вход к панели НЕ пускает (403 need2fa). Без ярлыка список врал бы
      // «устройств с активным входом: 3», когда полноценных два, а третье — чужой подобранный
      // пароль, застрявший перед кодом. Уровень считает роутер (поле level строки сессии), а
      // «включён ли 2FA» приезжает ТЕМ ЖЕ ответом (поле on) — без 2FA уровень ничего не значит.
      // СРОК — ВИДИМЫМ: с «Запомнить меня» сессии разной длины (год против 12 часов), и дату считает РОУТЕР (поле expires) —
      // своей арифметики «плюс год» во фронте нет, иначе список расходился бы с самой сессией.
      return '<div class="lrow"><div class="grow"><div class="nm"><span>'+esc(tfaUaName(s.ua))+'</span>'
        + (s.cur ? ' <span class="chip acc sm">это устройство</span>' : '')
        + ((totpOn && s.level===1) ? ' <span class="chip wr sm" title="пароль принят, код второго фактора ещё не вводили — панель такому входу не открыта">без кода</span>' : '')+'</div>'
        + '<div class="ds"><span>вошли '+esc(tfaWhen(s.issued))+'</span>'+(s.expires ? ' · <span>сессия до '+esc(tfaWhen(s.expires))+'</span>' : '')+' · '+addr+'</div></div>'
        + '<button type="button" class="btn sm gh tfa-kill" data-sid="'+esc(s.id)+'" data-cur="'+(s.cur?1:0)+'">Отвязать</button></div>';
    }).join('');
  }
  // Список — по кнопке «Показать устройства» (экран «Доступ к панели»); раскрытый в этот визит, он перерисовывается вместе с экраном.
  function paDevices(fsig){   // fsig — примета фокуса ДО перерисовки экрана (строки приходят позже отдельным запросом)
    var box=document.getElementById('pa-sess'); if(!box) return;
    var btn=document.getElementById('pa-list'), hadF=!!(btn && document.activeElement===btn);
    if(btn) btn.style.display='none';
    box.innerHTML='<div class="cline">загружаю…</div>';
    tfaPost('sessions','').then(function(d){
      if(!screenAlive(box)) return;
      if(!d || !d.ok){ box.innerHTML='<div class="cline wr">Не удалось получить список устройств.</div>'; return; }
      box.innerHTML=tfaSessRows(d.sessions||[], !!d.on);
      // Примета «Отвязать» (соседняя строка) — только пока фокус никто не занял: человек ушёл на тумблер — список, приехавший следом,
      // его не уводит. Скрытая кнопка «Показать» уронила фокус в BODY — он идёт в список, к первой строке (ревью шага 7a).
      var pf=_paDevFocus; _paDevFocus=null;
      var fa=document.activeElement, free=!fa || fa===document.body || fa===btn || box.contains(fa);
      var ft=(pf && pf.g===_navGen && free) ? (box.querySelector(pf.s) || document.querySelector('#modal-body [data-paa="all"]'))
            : (hadF && free) ? (box.querySelector('.tfa-kill') || document.querySelector('#modal-body [data-paa="all"]')) : null;
      if(ft) try{ ft.focus({preventScroll:true}); }catch(x){}
      // Экран перерисовали (опрос установки, тумблер), пока фокус стоял на строке списка: сама перерисовка вернуть его не могла — строк ещё
      // не было, и он падал в BODY (ревью шага 7a, круг 2). Возвращаем по примете, только если его никто не занял.
      else if(fsig && (!fa || fa===document.body)) focusBack(box, fsig);
      Array.prototype.forEach.call(box.querySelectorAll('.tfa-kill'), function(el){
        el.addEventListener('click', function(){
          var self=el.getAttribute('data-cur')==='1';
          if(!askConfirm(self?'Отвязать ЭТО устройство?\n\nПри следующем запросе панель попросит войти заново.'
                          :'Отвязать это устройство?\n\nПри следующем заходе с него панель попросит войти заново.')) return;
          // Строки не станет — фокус к соседней «Отвязать», последней — к «Выйти на всех» (разбор у nwNeighbor). Своей приметой, а
          // не `_nwFocus`: список приходит отдельным запросом ПОСЛЕ перерисовки экрана, и общая примета к этому мигу уже истрачена.
          _paDevFocus={s:nwNeighbor(box, 'data-sid', el, '[data-paa="all"]'), g:_navGen};
          tfaPost('revoke','',el.getAttribute('data-sid')).then(function(r){
            if(r && r.ok){ showToast(r.msg||'устройство отвязано', true); navIfShown('pn-access', openAccess)(); }
            else { _paDevFocus=null; showToast((r && r.msg) || 'не получилось', false); }
          }, function(){ _paDevFocus=null; showToast('нет связи с роутером', false); });
        });
      });
    }, function(){ if(screenAlive(box)) box.innerHTML='<div class="cline wr">Нет связи с роутером.</div>'; });
  }
  var _tfaTimer=null;
  function tfaLock(el, sec, lockEnd){        // «подождите N с» — счётчик паузы после серии неудач; `lockEnd` — пауза кончилась
    // СРОК, А НЕ СЧЁТ ТИКОВ: фоновую вкладку браузер будит реже (Chrome — раз в минуту после пяти минут), и счёт тиков растягивал
    // паузу до 15 минут в разы — окно говорило «подождите», когда роутер давно пускал (ревью шага 8a).
    var end=Date.now()+(sec|0)*1000;
    if(_tfaTimer){ clearInterval(_tfaTimer); _tfaTimer=null; }
    function tick(){
      // Узел мог уехать из документа РАНЬШЕ нуля: закрыли модалку с вопросом кода, форма входа
      // сменилась окном кода. Фоновый цикл, не спрашивающий «жив ли экран», — ровно тот класс,
      // от которого в панели заведён screenAlive; здесь достаточно проверки на документ.
      // Гард — тот же, что у остальных фоновых циклов панели: `screenAlive` знает и про
      // отцепленный узел, и про закрытую модалку (closeModal снимает класс, узел оставляет).
      // Для оверлеев входа модалки нет — там достаточно проверки на документ.
      var live = (el && document.body.contains(el)) &&
                 (!el.closest || !el.closest('#modal-body') || (typeof screenAlive!=='function') || screenAlive(el));
      if(!live){ clearInterval(_tfaTimer); _tfaTimer=null; return; }
      var left=Math.ceil((end-Date.now())/1000);
      if(left<=0){ clearInterval(_tfaTimer); _tfaTimer=null; el.textContent=''; if(lockEnd) lockEnd(); return; }
      el.textContent=tfaLockText(left);   // неразрывный: «18» и «с» на разных строках — замер 320 px
    }
    // Интервал назначаем ДО первого тика: гард внутри tick() гасит `_tfaTimer`, а если тик
    // бежит раньше присваивания, гасить нечего — и свежий интервал живёт лишнюю секунду.
    _tfaTimer=setInterval(tick, 1000); tick();
  }
  // Текст отсчёта паузы — одна запись на строку отсчёта и на невидимый хвост причины (его произносит читалка). Пробел перед «с» —
  // неразрывный: «18» и «с» ложились на разные строки (замер 320 px).
  function tfaLockText(left){ return 'слишком много попыток, подождите: ' + left + '\u00a0с'; }
  // Хвост для читалки — ДЛИТЕЛЬНОСТЬ паузы, а не остаток: хвост не меняется по секундам (иначе читалка говорила бы каждую), и
  // «подождите: 60 с», перечитанное через минуту, врало бы рядом с живым отсчётом «2 с» (ревью шага 8a, круг 3).
  function tfaPauseText(sec){ return 'вход приостановлен на ' + sec + '\u00a0с'; }
  var TFA_LOCK_MSG='слишком много неудачных попыток';   // так отвечает роутер, пока пауза идёт (cgi-bin/login, cgi-bin/2fa)
  // ОТКАЗ ПО ПАРОЛЮ ИЛИ КОДУ — одна запись на все четыре окна (форма входа, окно кода, выключение фактора, перевыпуск кодов):
  // причина — в строку с `role=alert`, пауза — отсчётом в свою строку БЕЗ alert (разбор у `.ferr` в panel.css). Причину держим и
  // тогда, когда она сама говорит о паузе («слишком много неудачных попыток»): это ЕДИНСТВЕННОЕ, что про паузу произнесёт читалка
  // — отсчёт она нарочно не объявляет, иначе говорила бы каждую секунду.
  // Пауза кончилась — причина больше не про «сейчас»: роутер снова пускает, а «слишком много неудачных попыток» без отсчёта
  // читалась бы вечным запретом (ревью шага 8a). Снимаем её, только если строку никто не сменил (под английским в ней перевод).
  // ПАУЗУ ЧИТАЛКА СЛЫШИТ СО СРОКОМ И ОДИН РАЗ (ревью шага 8a, круг 2): строка отсчёта нарочно без alert, а причина пятой неудачи —
  // «пароль не подошёл» — о паузе молчит, и человек узнавал о ней только следующей попыткой, а срок не слышал никогда. Поэтому в
  // строку причины (она alert) идёт НЕВИДИМЫЙ хвост с первым показом отсчёта; видимые строки прежние, по секундам никто не говорит.
