  // «слишком много неудачных попыток», не «пароль не подошёл» (ревью шага 8a, круг 3).
  function tfaRefuse(err, lk, d, def){
    var lock=(d && lk) ? Math.max(0, d.lock|0) : 0, m=(d && d.msg) ? d.msg : (lock ? TFA_LOCK_MSG : def);
    if(!err){ if(lock) tfaLock(lk, lock); return; }
    var sr=lock ? tfaPauseText(lock) : '';
    err.innerHTML=esc(m)+(sr ? ' <span class="sr-only">'+esc(sr)+'</span>' : '');
    if(!lock) return;
    var ru=err.textContent, en=trNow(m)+' '+trNow(sr);
    tfaLock(lk, lock, function(){ if(err.textContent===ru || err.textContent===en) err.textContent=''; });
  }
  // ОТВЕТ НА ВХОД — С ПОТОЛКОМ (ревью шага 8a, круг 2): своего срока у fetch нет, и роутер, не ответивший на вход (завис CGI,
  // оборвался канал), держал «Войти» запертой навсегда — Enter не пускает гард «запрос в воздухе», выход был только перезагрузкой
  // страницы, о которой окно не говорит. Сверка пароля на BE7000 — ~0,02 с (замер 24.09.2026), весь вход — доли секунды; 20 с —
  // заведомо «не ответит». Поздний ответ после потолка не нужен: человек уже видит, что делать, и повторит.
  // ПОЗДНИЙ УСПЕХ — ВСЁ ЖЕ ВХОД (ревью шага 8a, круг 3): роутер его уже исполнил — у кода сессия повышена, а сам код съеден защитой
  // от повтора (повтор тем же кодом дал бы «код не подошёл» и шаг к паузе), у пароля — сессия уже выпущена. Его отдаём в `late`.
  var TFA_WAIT=20000;
